from rules import amount


def solve(data):
    events = data['events']
    cutoff = data.get('cutoff', 10**9)
    selected = {}

    for position, event in enumerate(events):
        if event.get('sequence', 0) > cutoff:
            continue

        event_id = event.get('id')
        key = ('anonymous', position) if event_id is None else ('id', event_id)
        revision = event.get('revision', 0)
        previous = selected.get(key)
        if previous is None or revision >= previous[0]:
            selected[key] = (revision, position)

    balances = dict(data.get('opening', {}))
    winning_positions = {revision_position[1] for revision_position in selected.values()}
    for position, event in enumerate(events):
        if position not in winning_positions or event.get('void', False):
            continue

        key = f"{event.get('account', 'default')}|{event.get('currency', 'USD')}"
        balances.setdefault(key, 0)
        balances[key] += amount(event, data['rounding'])

    return {'balances': balances}
